from datetime import date

def dias_ate_proximo_aniversario(data_nascimento, hoje):
    aniversario_este_ano = date(hoje.year, data_nascimento.month, data_nascimento.day)

    if aniversario_este_ano < hoje:
        aniversario_este_ano = date(hoje.year + 1, data_nascimento.month, data_nascimento.day)

    return (aniversario_este_ano - hoje).days

